private void doUpdateUI() {
    String str;
    if (this.mUnit == null || !scene().currentFrame().findUnitByExactName(this.mUnit.getName()).isPresent()) {
        this.mRoot.setVisibility(8);
        return;
    }
    Item itemFindItemByFullName = Manifest.getInstance().findItemByFullName(this.mUnit.getName());
    if (itemFindItemByFullName == null) {
        this.mRoot.setVisibility(8);
        Log.e(TAG, "No item " + this.mUnit.getName());
        return;
    }
    this.mRoot.setVisibility(0);
    this.mOpacitySeeker.setProgress((int) (this.mUnit.getAlpha() * 100.0f));
    if (EnvUtils.isTablet()) {
        this.mThumb.setVisibility(0);
        this.mThumb.setImageBitmap(ItemDataFetcher.getThumb(itemFindItemByFullName));
    } else {
        this.mThumb.setVisibility(8);
    }
    this.mCustomEdit.setVisibility(!ItemInformation.isEditableAsCustom(itemFindItemByFullName.getFullName()) ? 8 : 0);
    UIUtils.setButtonEnabled(this.mUp, this.mUnit.getOwnFrame().canRearrange(this.mUnit, true));
    UIUtils.setButtonEnabled(this.mDown, this.mUnit.getOwnFrame().canRearrange(this.mUnit, false));
    this.mFace.setVisibility(8);
    this.mDetach.setVisibility(this.mUnit.isEnslaved() ? 0 : 8);
    TreeSet<Integer> states = stage().mUnitsAssets.getStates(this.mUnit.getName());
    this.mSetText.setVisibility(this.mUnit instanceof SpeechBubble ? 0 : 8);
    boolean z = scene().mMasks.getMode(this.mUnit) != Masks.MODE.NO;
    UIUtils.setButtonEnabled(this.mCopy, !z);
    UIUtils.setButtonEnabled(this.mOpenOpacity, !z);
    this.mOpenStates.setVisibility(states.size() > 1 ? 0 : 8);
    Bitmap bitmapDecodeResource = BitmapFactory.decodeResource(getResources(), scene().getUnitLatch().has() ? R.drawable.props_unlock_others : R.drawable.props_lock_others);
    BitmapDrawable bitmapDrawable = new BitmapDrawable(getResources(), bitmapDecodeResource);
    bitmapDrawable.setBounds(0, 0, bitmapDecodeResource.getWidth(), bitmapDecodeResource.getHeight());
    this.mLock.setCompoundDrawables(null, bitmapDrawable, null, null);
    if (!scene().mMasks.isConvertingToMaskAllowed(this.mUnit.getName())) {
        this.mMask.setVisibility(8);
    } else {
        this.mMask.setVisibility(0);
        Bitmap bitmapDecodeResource2 = BitmapFactory.decodeResource(getResources(), scene().mMasks.isUnitActiveMask(this.mUnit) ? R.drawable.props_mask_sel : R.drawable.props_mask_unselected);
        BitmapDrawable bitmapDrawable2 = new BitmapDrawable(getResources(), bitmapDecodeResource2);
        bitmapDrawable2.setBounds(0, 0, bitmapDecodeResource2.getWidth(), bitmapDecodeResource2.getHeight());
        this.mMask.setCompoundDrawables(null, bitmapDrawable2, null, null);
    }
    this.mCaption.setVisibility(0);
    if (this.mUnit.getNumber() == 0 && frame().findInstancesOfUnitByName(this.mUnit.getName()).size() == 1) {
        str = itemFindItemByFullName.mHumanName;
    } else {
        str = String.format(Locale.getDefault(), "%s(%d)", itemFindItemByFullName.mHumanName, Integer.valueOf(this.mUnit.getNumber()));
    }
    int currentIndex = scene().getCurrentIndex();
    String name = this.mUnit.getName();
    boolean zIsAutoTweenLocked = scene().tweens().isAutoTweenLocked(name, currentIndex);
    boolean zIsAutoTweenStructureLocked = scene().tweens().isAutoTweenStructureLocked(scene(), name, currentIndex);
    if (zIsAutoTweenLocked || zIsAutoTweenStructureLocked) {
        str = str + " [AUTO]";
    }
    this.mCaption.setText(str);
    this.mStatesAdapter.update();
    this.mTween.setText(zIsAutoTweenStructureLocked ? "Tween (AUTO)" : "Tween");
    if (zIsAutoTweenLocked) {
        setAllPropButtonsEnabled(false);
        return;
    }
    setAllPropButtonsEnabled(true);
    UIUtils.setButtonEnabled(this.mUp, this.mUnit.getOwnFrame().canRearrange(this.mUnit, true));
    UIUtils.setButtonEnabled(this.mDown, this.mUnit.getOwnFrame().canRearrange(this.mUnit, false));
    UIUtils.setButtonEnabled(this.mCopy, !z);
    UIUtils.setButtonEnabled(this.mOpenOpacity, !z);
    if (zIsAutoTweenStructureLocked) {
        UIUtils.setButtonEnabled(this.mDetach, false);
        UIUtils.setButtonEnabled(this.mLock, false);
        UIUtils.setButtonEnabled(this.mTween, false);
        UIUtils.setButtonEnabled(this.mAdvanced, false);
    }
}
